internal.body:
      if (mode <= 0 || mode > MAX_MODE) {
        throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
	  }
      double maxPowerLevel = washingMachine.getMaxPowerLevelJava4();
      return (mode - 1) * maxPowerLevel/(MAX_MODE - 1);

      if (newPowerLevel < 0.0) {
		throw new fr.sorbonne_u.exceptions.PreconditionException("newPowerLevel >= 0.0");
	  }
      double maxPowerLevel = washingMachine.getMaxPowerLevelJava4();
      if (newPowerLevel > maxPowerLevel) {
		newPowerLevel = maxPowerLevel;
	  }
      washingMachine.setCurrentPowerLevelJava4(newPowerLevel);

      if (newMode <= 0 || newMode > MAX_MODE) {
        throw new fr.sorbonne_u.exceptions.PreconditionException("newMode > 0 && newMode <= MAX_MODE");
	  }
      double newPowerLevel = computePowerLevel(newMode);
      setPowerLevel(newPowerLevel);

upMode.body:
try {
  computeAndSetNewPowerLevel(currentMode + 1);
  currentMode++;
} catch(Exception e) {
  return false;
}
return true;

downMode.body:
try {
  computeAndSetNewPowerLevel(currentMode - 1);
  currentMode--;
} catch(Exception e) {
  return false;
}
return true;

setMode.body:
try {
  computeAndSetNewPowerLevel(modeIndex);
  currentMode = modeIndex;
} catch(Exception e) {
  return false;
}
return true;

suspend.body:
try {
  washingMachine.setCurrentPowerLevelJava4(0.0);
  isSuspended = true;
} catch(Exception e) {
  return false;
}
return true;

resume.body:
try {
  computeAndSetNewPowerLevel(currentMode);
  isSuspended = false;
} catch(Exception e) {
  return false;
}
return true;

emergency.body:
double currentTemperature = washingMachine.getCurrentTemperatureJava4();
double targetTemperature = washingMachine.getTargetTemperatureJava4();
double delta = Math.abs(targetTemperature - currentTemperature);
double ret = -1.0;
if (currentTemperature < MIN_ADMISSIBLE_TEMP ||
                              delta >= MAX_ADMISSIBLE_DELTA) {
  ret = 1.0;
} else {
  ret = delta/MAX_ADMISSIBLE_DELTA;
}
return ret;
